package pe.vichaval.gestionriego.caja.entity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;import pe.vichaval.gestionriego.caja.dto.EgresoForm;import pe.vichaval.gestionriego.usuario.entity.Usuario;@Entity@Table(name="egresos")public class Egreso{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;private String codigo;private LocalDate fecha;private String concepto;private String descripcion;private BigDecimal monto;private String metodo;private String comprobante;private String estado="REGISTRADO";@Column(name="motivo_anulacion")private String motivoAnulacion;@ManyToOne@JoinColumn(name="usuario_id")private Usuario usuario;protected Egreso(){}public Egreso(String c,EgresoForm f,Usuario u){codigo=c;fecha=f.getFecha();concepto=f.getConcepto();descripcion=f.getDescripcion();monto=f.getMonto();metodo=f.getMetodo();comprobante=f.getComprobante();usuario=u;}public void anular(String m){if(!"REGISTRADO".equals(estado))throw new IllegalStateException("Egreso ya anulado");if(m==null||m.isBlank())throw new IllegalArgumentException("Motivo obligatorio");estado="ANULADO";motivoAnulacion=m;}public Long getId(){return id;}public String getCodigo(){return codigo;}public LocalDate getFecha(){return fecha;}public String getConcepto(){return concepto;}public BigDecimal getMonto(){return monto;}public String getMetodo(){return metodo;}public String getEstado(){return estado;}public Usuario getUsuario(){return usuario;}}
